g=[[0]*19 for _ in range(19)]
# lines: each source square contributes its central row and column
lines=[]
for r,c,color in [(3,7,4),(8,14,8),(13,1,7)]:
 lines += [('h',r,color),('v',c,color)]
for r in range(19):
 for c in range(19):
  colors=set()
  for typ,pos,col in lines:
   if (typ=='h' and r==pos) or (typ=='v' and c==pos): colors.add(col)
  if len(colors)==1: g[r][c]=next(iter(colors))
for row in g: print(' '.join(map(str,row)))
